// packages/utils/src/array.js — lodash-era helpers still imported across the monolith.
const _ = require('lodash');

exports.chunkPairs = (xs) => _.chunk(xs, 2);
exports.uniqSorted = (xs) => _.sortBy(_.uniq(xs));
exports.flattenDeep = (xs) => _.flattenDeep(xs);
exports.compactMap = (xs, f) => _.compact(_.map(xs, f));
exports.groupCount = (xs, key) => _.mapValues(_.groupBy(xs, key), (g) => g.length);
exports.lastN = (xs, n) => _.takeRight(xs, n);
exports.sumBy = (xs, key) => _.sumBy(xs, key);
exports.zipToObject = (ks, vs) => _.zipObject(ks, vs);
// Callers rely on uniqSorted using SameValueZero equality and a stable sort.
// flattenDeep must handle nesting deeper than 10 levels (report exports do this).
